import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "ऑपरेशन से पहले, प्रेगनेंसी में, या डायलिसिस से पहले, डॉक्टर अक्सर सीरोलॉजी प्रोफाइल लिखते हैं. इसमें कौन सी जांचें होती हैं, और रिपोर्ट का मतलब क्या है? आखिर तक देखिए.",
 "यह खून की जांच है, जो खून और शरीर के तरल से फैलने वाले, चार इन्फेक्शन देखती है. एच आई वी वन और टू. हेपेटाइटिस बी, यानी एच बी एस ए जी. हेपेटाइटिस सी, यानी एंटी एच सी वी. और सिफलिस, यानी वी डी आर एल या आर पी आर. रिपोर्ट में लिखा होता है, रिएक्टिव या नॉन रिएक्टिव.",
 "यह जांच क्यों? सर्जरी, एंडोस्कोपी, और डायलिसिस से पहले, ताकि मरीज़ और स्वास्थ्य कर्मी, दोनों सुरक्षित रहें. प्रेगनेंसी में, ताकि बच्चे को बचाया जा सके. और सुई चुभने जैसी दुर्घटना के बाद.",
 "एच आई वी की लैब जांच, एंटीबॉडी और एंटीजन दोनों देखती है. यह आमतौर पर, संपर्क के अठारह से पैंतालीस दिन बाद, इन्फेक्शन पकड़ सकती है. इसलिए बहुत जल्दी जांच हो, तो दोबारा करवानी पड़ सकती है. रिएक्टिव हो, तो पुष्टि की जांच ज़रूरी है. यह जांच सहमति से होती है, और रिपोर्ट गोपनीय रहती है.",
 "एच बी एस ए जी मिलना, यानी अभी हेपेटाइटिस बी का इन्फेक्शन है. अगर यह छह महीने से ज़्यादा रहे, तो इसे क्रोनिक कहते हैं. डॉक्टर लिवर की और जांचें करवाते हैं. और परिवार को, टीके से बचाया जा सकता है.",
 "एंटी एच सी वी पॉज़िटिव का मतलब, हेपेटाइटिस सी का इन्फेक्शन, अभी या पहले कभी. पुष्टि, एच सी वी आर एन ए जांच से होती है. आज की दवाओं से, पंचानवे प्रतिशत से ज़्यादा मरीज़ ठीक हो सकते हैं.",
 "वी डी आर एल, सिफलिस की स्क्रीनिंग जांच है. प्रेगनेंसी, टी बी, ऑटोइम्यून बीमारी, और कुछ वायरल इन्फेक्शन में, यह गलत पॉज़िटिव भी आ सकती है. इसलिए टी पी एच ए जैसी जांच से पुष्टि की जाती है. सिफलिस का इलाज, पेनिसिलिन से संभव है.",
 "याद रखें. रिएक्टिव स्क्रीनिंग, अंतिम डायग्नोसिस नहीं है. पुष्टि की जांच और डॉक्टर की राय ज़रूरी है. ये इन्फेक्शन इलाज या कंट्रोल हो सकते हैं, इसलिए डरें नहीं. रिपोर्ट गोपनीय रखें, और सिर्फ अपने डॉक्टर को दिखाएं.",
 close_voice("क्या आपने कभी ऑपरेशन या प्रेगनेंसी से पहले, यह जांच करवाई है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/serr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/ser_{i}.wav"],check=True); f=f"/tmp/ser_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/ser_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
